import{_ as e,o as i,c as t,ag as n}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"科学日报 · 2026-10-29（生物医学 / 心肌代谢 · 乳酸直入线粒体）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/biomedicine/science-daily-2026-10-29-biomed.md","filePath":"topics/biomedicine/science-daily-2026-10-29-biomed.md"}'),c={name:"topics/biomedicine/science-daily-2026-10-29-biomed.md"};function s(r,o,d,l,a,g){return i(),t("div",null,[...o[0]||(o[0]=[n('<h1 id="科学日报-·-2026-10-29-生物医学-心肌代谢-·-乳酸直入线粒体" tabindex="-1">科学日报 · 2026-10-29（生物医学 / 心肌代谢 · 乳酸直入线粒体） <a class="header-anchor" href="#科学日报-·-2026-10-29-生物医学-心肌代谢-·-乳酸直入线粒体" aria-label="Permalink to &quot;科学日报 · 2026-10-29（生物医学 / 心肌代谢 · 乳酸直入线粒体）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-29.md</code> — 第48期 ｜ 科学板块（1 篇） 落盘说明：文件名带 <code>-biomed</code> 后缀，避免与其它主题同日同名文件互引产生伪边（见 <code>topics/ai-brain/auto-link-quality-fixes.md</code>）。</p></blockquote><hr><h2 id="科学日报-2026-10-29-心脏的「乳酸捷径」——mct1-把乳酸直接搬进线粒体供能" tabindex="-1">科学日报 2026-10-29：心脏的「乳酸捷径」——MCT1 把乳酸直接搬进线粒体供能 <a class="header-anchor" href="#科学日报-2026-10-29-心脏的「乳酸捷径」——mct1-把乳酸直接搬进线粒体供能" aria-label="Permalink to &quot;科学日报 2026-10-29：心脏的「乳酸捷径」——MCT1 把乳酸直接搬进线粒体供能&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-29.md</code> ｜ DOI: 10.1038/s41586-026-11182-3 ｜ Nature (2026)</p></blockquote><ul><li>问题：心脏能灵活氧化葡萄糖、乳酸等多种燃料以应对饮食/运动/损伤应激。传统观点认为<strong>糖类氧化都要先走胞质生成丙酮酸、再由线粒体丙酮酸载体（MPC）进入 TCA 循环</strong>——那么 <strong>MPC 一旦缺失，糖碳还能不能进线粒体？</strong></li><li>方法：<strong>遗传敲除 MPC</strong> + 心肌代谢/生理测量 + MCT1（Slc16a1）功能定位。</li><li>结果（实测）： <ul><li><strong>敲除 MPC 后，小鼠心肌仍能氧化葡萄糖来源的碳</strong>；这条备用通路<strong>依赖单羧酸转运体 MCT1（Slc16a1）</strong>；</li><li>通常定位在<strong>质膜</strong>的 <strong>MCT1 也存在于小鼠与人心肌细胞的线粒体内膜</strong>——与基质中的 <strong>LDHB</strong> 搭档，<strong>在线粒体内把乳酸转成丙酮酸与 NADH</strong>，<strong>直接给电子传递链供料</strong>；</li><li><strong>缺失 MCT1</strong> 会损害乳酸氧化、<strong>破坏代谢灵活性</strong>，并在<strong>神经内分泌轴过度激活或缺血—再灌注损伤后加速心衰、增加死亡率</strong>。</li></ul></li><li>洞察（对本库 <code>biomedicine</code> × 10-25/10-26 线粒体主线）： <ol><li><strong>「同一分子在第二个位置干第二件事」= 亚细胞定位即功能</strong> —— MCT1 不只做「跨质膜运乳酸」，还能在<strong>线粒体内膜</strong>上把乳酸<strong>就地</strong>转成燃料。判据：<strong>当一个分子「已知功能」无法解释表型时，先查它是否还有第二个亚细胞定位。</strong> 这与 10-10 高尔基体来源 PI(3,4)P₂ 囊泡驱动线粒体融合、10-25「cytochrome c 与 mtDNA 由不同复合体分别外流」同族——<strong>细胞器的「膜上转运/定位」层反复出现新的功能分工。</strong></li><li><strong>「被忽视的平行通路才是代谢灵活性的来源」</strong> —— 关键不在丙酮酸这条主干道，而在<strong>平行于它的乳酸通道</strong>是可被敲除后仍维持供能的冗余。判据：<strong>当一条通路被敲除而表型不变时，优先去找可能平时「沉默」的平行通路，而不是怀疑敲除失效。</strong> 这与 10-24（对应内容见本库同周笔记）「冗余设计隐藏脆弱点」同族。</li><li><strong>一句话定位</strong>：心脏代谢的<strong>瓶颈可能不在丙酮酸，而在乳酸入线粒体这条通路</strong>——为心衰/缺血—再灌注提供<strong>可干预的代谢靶点</strong>。</li></ol></li></ul><hr><blockquote><p>📎 关联主题：<code>topics/biomedicine/index.md</code> ｜ 第48期 科学板块</p></blockquote><p>关键词：科学日报第48期、心肌代谢、乳酸氧化、MCT1、Slc16a1、单羧酸转运体、线粒体内膜、LDHB、乳酸脱氢酶 B、线粒体丙酮酸载体 MPC、代谢灵活性 metabolic flexibility、缺血再灌注、神经内分泌过度激活、心衰、亚细胞定位即功能、平行通路冗余、心脏燃料</p><p>关联：<code>topics/biomedicine/index.md</code>、<code>topics/biomedicine/science-daily-2026-10-26-biomed.md</code>（TPGS 凝胶/线粒体与免疫）、<code>topics/biomedicine/science-daily-2026-10-25-biomed.md</code>（BAX-BAK 与 mtDNA 外流）、<code>topics/biomedicine/science-daily-2026-10-12.md</code>（人类心脏发育单细胞图谱）、<code>topics/neuroscience/science-daily-2026-10-29-neuro.md</code></p>',10)])])}const b=e(c,[["render",s]]);export{p as __pageData,b as default};
